from ortools.sat.python import cp_model
import json

def main():
    n_components = 10
    n_stations = 5

    processing_times = [
        [10, 15, 12, 18, 14],
        [20, 25, 22, 28, 24],
        [30, 35, 32, 38, 34],
        [40, 45, 42, 48, 44],
        [50, 55, 52, 58, 54],
        [60, 65, 62, 68, 64],
        [70, 75, 72, 78, 74],
        [80, 85, 82, 88, 84],
        [90, 95, 92, 98, 94],
        [100,105,102,108,104],
    ]
    p = processing_times

    M = sum(sum(row) for row in p)

    model = cp_model.CpModel()

    start_time = {}
    finish_time = {}
    for i in range(n_components):
        for j in range(n_stations):
            start_time[(i,j)] = model.NewIntVar(0, M, f"s_{i}_{j}")
            finish_time[(i,j)] = model.NewIntVar(0, M, f"f_{i}_{j}")

    y = {}
    for i in range(n_components):
        for k in range(i+1, n_components):
            for j in range(n_stations):
                y[(i,k,j)] = model.NewBoolVar(f"y_{i}_{k}_{j}")

    C_max = model.NewIntVar(0, M, "C_max")

    for i in range(n_components):
        for j in range(n_stations):
            model.Add(finish_time[(i,j)] == start_time[(i,j)] + p[i][j])

    for i in range(n_components):
        for j in range(n_stations - 1):
            model.Add(start_time[(i,j+1)] >= finish_time[(i,j)])

    for j in range(n_stations):
        for i in range(n_components):
            for k in range(i+1, n_components):
                model.Add(start_time[(k,j)] >= finish_time[(i,j)]).OnlyEnforceIf(y[(i,k,j)])
                model.Add(start_time[(i,j)] >= finish_time[(k,j)]).OnlyEnforceIf(y[(i,k,j)].Not())

    for i in range(n_components):
        model.Add(C_max >= finish_time[(i, n_stations-1)])

    model.Minimize(C_max)

    solver = cp_model.CpSolver()
    solver.parameters.max_time_in_seconds = 300.0
    solver.parameters.num_search_workers = 8

    status = solver.Solve(model)

    if status not in (cp_model.OPTIMAL, cp_model.FEASIBLE):
        return

    makespan = solver.Value(C_max)

    first_station_starts = [(solver.Value(start_time[(i,0)]), i) for i in range(n_components)]
    first_station_starts.sort()

    component_sequence = [idx + 1 for _, idx in first_station_starts]

    print(json.dumps({
        "component_sequence": component_sequence,
        "total_production_time": makespan
    }))

if __name__ == "__main__":
    main()
